static const char *const categories[10] = {
    "SCIENCE & SPACE", "TECH & COMPUTING", "WORLD HISTORY",
    "WORLD GEOGRAPHY", "CULTURE & SOCIETY", "ART & LITERATURE",
    "MOVIES, TV & ANIMATION", "SPORTS", "LOGIC & MATH",
    "GENERAL KNOWLEDGE"
};

static int order[200], aorder[4];
static int category = 0, selected = 0, q = 0, pos = 0;
static int score = 0, state = 0;
static bool was_correct = false;

static int rnd(int max)
{
    return max > 0 ? rand() % max : 0;
}

static void shuffle_answers(void)
{
    for (int i = 0; i < 4; i++)
        aorder[i] = i;

    for (int i = 3; i > 0; i--) {
        int j = rnd(i + 1);
        int t = aorder[i];
        aorder[i] = aorder[j];
        aorder[j] = t;
    }
}

static void load_q(void)
{
    q = category * 200 + order[pos];
    selected = 0;
    shuffle_answers();
}

static void start_round(void)
{
    for (int i = 0; i < 200; i++)
        order[i] = i;

    for (int i = 199; i > 0; i--) {
        int j = rnd(i + 1);
        int t = order[i];
        order[i] = order[j];
        order[j] = t;
    }

    pos = 0;
    score = 0;
    state = 1;
    load_q();
}

static void submit(void)
{
    if (state == 1) {
        was_correct = (aorder[selected] == correct_answer[q]);

        if (was_correct)
            score++;

        state = 2;
    }
}

static void advance_q(void)
{
    if (pos < 9) {
        pos++;
        load_q();
        state = 1;
    } else {
        state = 3;
    }
}

/* Graphics helpers */
static void txt(int s, int x, int y, uint32_t c, const char *t)
{
    gfx_print(s, x, y, FONT_REGULAR, c, "%s", t);
}

static void num(int s, int x, int y, uint32_t c, int n)
{
    char b[24];
    snprintf(b, sizeof(b), "%d", n);
    txt(s, x, y, c, b);
}

static void panel(int s, int x, int y, int w, int h, uint32_t c)
{
    gfx_round_rect(s, x, y, w, h, 8, c);
}

/* Home screen — top */
static void menu_top(void)
{
    gfx_clear(SCREEN_TOP, BG);
    gfx_gradient(SCREEN_TOP, 0, 0, 400, 7, MINT, MINT);

    panel(SCREEN_TOP, 16, 18, 368, 38, PANEL);
    txt(SCREEN_TOP, 28, 29, MINT, "QUIZ3DS");
    txt(SCREEN_TOP, 160, 29, WHITE, "THE KNOWLEDGE DECK");

    panel(SCREEN_TOP, 16, 68, 368, 112, PANEL);
    txt(SCREEN_TOP, 28, 80, MUTED, "SELECTED CATEGORY");
    txt(SCREEN_TOP, 28, 101, WHITE, categories[category]);
    txt(SCREEN_TOP, 28, 126, MINT, "200 QUESTIONS AVAILABLE");
    txt(SCREEN_TOP, 28, 145, MUTED, "10 RANDOM QUESTIONS PER ROUND");

    panel(SCREEN_TOP, 16, 192, 368, 32, PANEL2);
    txt(SCREEN_TOP, 28, 204, WHITE,
        "2,000 QUESTIONS  |  10 CATEGORIES");
}

/* Home screen — bottom */
static void menu_bottom(void)
{
    gfx_clear(SCREEN_BOTTOM, BG);
    txt(SCREEN_BOTTOM, 12, 5, MINT, "CHOOSE A CATEGORY");

    for (int i = 0; i < 10; i++) {
        int y = 22 + i * 19;
        uint32_t bg = (i == category) ? MINT : PANEL;
        uint32_t fg = (i == category) ? BG : WHITE;

        panel(SCREEN_BOTTOM, 8, y, 304, 17, bg);
        num(SCREEN_BOTTOM, 14, y + 4, fg, i + 1);
        txt(SCREEN_BOTTOM, 31, y + 4, fg, categories[i]);
    }

    txt(SCREEN_BOTTOM, 12, 228, MUTED,
        "UP/DOWN + A: PLAY  |  TOUCH TO PLAY");
}

/* Question screen — top */
static void question_top(void)
{
    gfx_clear(SCREEN_TOP, BG);

    panel(SCREEN_TOP, 0, 0, 400, 48, PANEL);
    txt(SCREEN_TOP, 16, 8, MINT, "QUIZ3DS");
    txt(SCREEN_TOP, 16, 26, WHITE, categories[category]);

    txt(SCREEN_TOP, 294, 8, MUTED, "Q");
    num(SCREEN_TOP, 312, 8, WHITE, pos + 1);
    txt(SCREEN_TOP, 344, 8, MUTED, "/10");

    panel(SCREEN_TOP, 16, 54, 368, 5, PANEL2);
    panel(SCREEN_TOP, 16, 54, 368 * (pos + 1) / 10, 5, MINT);

    panel(SCREEN_TOP, 16, 70, 368, 112, PANEL);
    txt(SCREEN_TOP, 24, 78, MINT, "QUESTION");

    txt(SCREEN_TOP, 24, 99, WHITE, question_line1[q]);
    txt(SCREEN_TOP, 24, 117, WHITE, question_line2[q]);
    txt(SCREEN_TOP, 24, 135, WHITE, question_line3[q]);

    if (state == 2) {
        txt(SCREEN_TOP, 24, 162,
            was_correct ? GOOD : BAD,
            was_correct ? "CORRECT!" : "NOT QUITE");
    } else {
        txt(SCREEN_TOP, 24, 162, MUTED, "CHOOSE YOUR ANSWER");
    }

    panel(SCREEN_TOP, 16, 194, 368, 30, PANEL2);
    txt(SCREEN_TOP, 26, 205, MUTED, "SCORE");
    num(SCREEN_TOP, 94, 205, WHITE, score);
    txt(SCREEN_TOP, 220, 205, MUTED, "A: SELECT  /  B: MENU");
}

/* Answers screen — bottom */
static void answers_bottom(void)
{
    gfx_clear(SCREEN_BOTTOM, BG);
    txt(SCREEN_BOTTOM, 12, 5, MINT, "CHOOSE AN ANSWER");

    for (int i = 0; i < 4; i++) {
        int y = 22 + i * 49;
        int idx = q * 4 + aorder[i];
        uint32_t bg = (i == selected) ? MINT : PANEL;
        uint32_t fg = (i == selected) ? BG : WHITE;

        panel(SCREEN_BOTTOM, 12, y, 296, 43, bg);

        char letter[2] = { (char)('A' + i), '\0' };
        txt(SCREEN_BOTTOM, 21, y + 15, fg, letter);

        txt(SCREEN_BOTTOM, 42, y + 4, fg, answer_line1[idx]);
        txt(SCREEN_BOTTOM, 42, y + 17, fg, answer_line2[idx]);
        txt(SCREEN_BOTTOM, 42, y + 29, fg, answer_line3[idx]);
    }

    txt(SCREEN_BOTTOM, 8, 228, MUTED,
        "UP/DOWN: MOVE   A: SELECT   B: MENU");
}

/* Feedback screen — bottom */
static void feedback_bottom(void)
{
    gfx_clear(SCREEN_BOTTOM, BG);
    txt(SCREEN_BOTTOM, 16, 8, MINT, "ANSWER FEEDBACK");

    panel(SCREEN_BOTTOM, 12, 32, 296, 138, PANEL);

    txt(SCREEN_BOTTOM, 24, 43,
        was_correct ? GOOD : BAD,
        was_correct ? "NICE WORK!" : "CORRECT ANSWER");

    int idx = q * 4 + correct_answer[q];

    txt(SCREEN_BOTTOM, 24, 66, WHITE, answer_line1[idx]);
    txt(SCREEN_BOTTOM, 24, 82, WHITE, answer_line2[idx]);
    txt(SCREEN_BOTTOM, 24, 98, WHITE, answer_line3[idx]);

    txt(SCREEN_BOTTOM, 24, 137, MUTED, "SCORE");
    num(SCREEN_BOTTOM, 82, 137, WHITE, score);

    panel(SCREEN_BOTTOM, 16, 184, 288, 34, MINT);
    txt(SCREEN_BOTTOM, 48, 197, BG, "A / TOUCH: NEXT QUESTION");
    txt(SCREEN_BOTTOM, 16, 228, MUTED, "B: RETURN TO MENU");
}

/* Results screen — top */
static void results_top(void)
{
    gfx_clear(SCREEN_TOP, BG);
    gfx_gradient(SCREEN_TOP, 0, 0, 400, 7, MINT, MINT);

    txt(SCREEN_TOP, 24, 20, MINT, "QUIZ3DS");
    txt(SCREEN_TOP, 24, 58, WHITE, "ROUND COMPLETE");
    txt(SCREEN_TOP, 24, 82, MUTED, categories[category]);

    panel(SCREEN_TOP, 24, 112, 352, 64, PANEL);
    num(SCREEN_TOP, 42, 128, WHITE, score);
    txt(SCREEN_TOP, 82, 128, MUTED, "/ 10 CORRECT");

    txt(SCREEN_TOP, 42, 151, MINT, "NEW ROUND = NEW RANDOM ORDER");
    txt(SCREEN_TOP, 24, 202, MUTED, "TAKE A BREATH. THEN PLAY AGAIN.");
}

/* Results screen — bottom */
static void results_bottom(void)
{
    gfx_clear(SCREEN_BOTTOM, BG);
    txt(SCREEN_BOTTOM, 16, 8, MINT, "WHAT NEXT?");

    panel(SCREEN_BOTTOM, 16, 42, 288, 48, MINT);
    txt(SCREEN_BOTTOM, 32, 62, BG, "A  PLAY AGAIN");

    panel(SCREEN_BOTTOM, 16, 104, 288, 48, PANEL);
    txt(SCREEN_BOTTOM, 32, 124, WHITE, "B  CATEGORY MENU");

    txt(SCREEN_BOTTOM, 16, 176, MUTED, "10 NEW RANDOM QUESTIONS");
    txt(SCREEN_BOTTOM, 16, 192, MUTED, "EVERY ROUND STARTS FRESH");
    txt(SCREEN_BOTTOM, 16, 228, MUTED, "TOUCH A BUTTON OR USE A/B");
}

/* Render the current state */
static void frame(void)
{
    if (state == 0) {
        menu_top();
        menu_bottom();
    } else if (state == 1) {
        question_top();
        answers_bottom();
    } else if (state == 2) {
        question_top();
        feedback_bottom();
    } else {
        results_top();
        results_bottom();
    }
}

/* Main loop */
int main(void)
{
    while (app_loop()) {
        uint32_t k = hid_keys_down();
        bool tap = hid_touch_down();
        int tx = hid_touch_x();
        int ty = hid_touch_y();

        if (state == 0) {
            if (k & KEY_UP)
                category = (category + 9) % 10;

            if (k & KEY_DOWN)
                category = (category + 1) % 10;

            if (k & KEY_A)
                start_round();

            if (tap && tx >= 4 && tx < 316 &&
                ty >= 22 && ty < 212) {
                int r = (ty - 22) / 19;

                if (r >= 0 && r < 10 && ty < 22 + r * 19 + 17) {
                    category = r;
                    start_round();
                }
            }
        } else if (state == 1) {
            if (k & KEY_B) {
                state = 0;
            } else {
                if (k & KEY_UP)
                    selected = (selected + 3) % 4;

                if (k & KEY_DOWN)
                    selected = (selected + 1) % 4;

                if (k & KEY_A)
                    submit();

                if (tap && tx >= 12 && tx < 308 &&
                    ty >= 22 && ty < 212) {
                    int r = (ty - 22) / 49;

                    if (r >= 0 && r < 4 && ty < 22 + r * 49 + 43) {
                        selected = r;
                        submit();
                    }
                }
            }
        } else if (state == 2) {
            if (k & KEY_B)
                state = 0;
            else if (k & KEY_A)
                advance_q();
            else if (tap && tx >= 16 && tx < 304 &&
                     ty >= 184 && ty < 218)
                advance_q();
        } else {
            if (k & KEY_B)
                state = 0;
            else if (k & KEY_A)
                start_round();
            else if (tap && tx >= 16 && tx < 304 &&
                     ty >= 42 && ty < 90)
                start_round();
            else if (tap && tx >= 16 && tx < 304 &&
                     ty >= 104 && ty < 152)
                state = 0;
        }

        frame();
    }

    return 0;
}